/data/understat-reconciliation-2026-10-27.json","expected_rows":6},{"source_player_id":"9960","player_code":"240514","mapping_method":"canonical_match_history_goals_minutes_v1","source_note":"Unchanged resolver thresholds on positive-minute appearances; 100% two-sided match history, exact goals and teams, one-to-one unique. Zero-minute unused substitutes excluded as non-appearances. Official current-season FPL rows and goals independently agree. Names used only for QA. Audit: PL-Results-Project/data/understat-reconciliation-2026-10-27.json","expected_rows":4},{"source_player_id":"9977","player_code":"469272","mapping_method":"canonical_match_history_goals_minutes_v1","source_note":"Unchanged resolver thresholds on positive-minute appearances; 100% two-sided match history, exact goals and teams, one-to-one unique. Zero-minute unused substitutes excluded as non-appearances. Official current-season FPL rows and goals independently agree. Names used only for QA. Audit: PL-Results-Project/data/understat-reconciliation-2026-10-27.json","expected_rows":4},{"source_player_id":"12760","player_code":"472739","mapping_method":"canonical_match_history_goals_minutes_position_v1","source_note":"Exact 8-match team/goals history and minute patterns plus independently verified native Fotmob lineup role in all 8 matches. Fotmob ID already linked through official FPL Opta code. Role distinguishes goalkeeper, centre-back or left-back; names not used as identity evidence. Audit: PL-Results-Project/data/understat-reconciliation-2026-10-27.json","expected_rows":8},{"source_player_id":"14859","player_code":"483067","mapping_method":"canonical_match_history_goals_minutes_position_v1","source_note":"Exact 8-match team/goals history and minute patterns plus independently verified native Fotmob lineup role in all 8 matches. Fotmob ID already linked through official FPL Opta code. Role distinguishes goalkeeper, centre-back or left-back; names not used as identity evidence. Audit: PL-Results-Project/data/understat-reconciliation-2026-10-27.json","expected_rows":8},{"source_player_id":"8640","player_code":"494521","mapping_method":"canonical_match_history_goals_minutes_position_v1","source_note":"Exact 8-match team/goals history and minute patterns plus independently verified native Fotmob lineup role in all 8 matches. Fotmob ID already linked through official FPL Opta code. Role distinguishes goalkeeper, centre-back or left-back; names not used as identity evidence. Audit: PL-Results-Project/data/understat-reconciliation-2026-10-27.json","expected_rows":8}]$maps$::jsonb) as x(source_player_id text,player_code text,mapping_method text,source_note text,expected_rows integer);
do $$ begin
 if (select count(*) from remediation_mappings)<>121 or (select count(distinct player_code) from remediation_mappings)<>121 or (select count(distinct source_player_id) from remediation_mappings)<>121 then raise exception 'Mapping cardinality failed'; end if;
 if exists(select 1 from remediation_mappings n left join players p using(player_code) where p.player_code is null or p.player_code ~ '^(understat|tm|fotmob|sofascore):') then raise exception 'Invalid canonical identity'; end if;
 if exists(select 1 from remediation_mappings n join player_source_ids p on p.source='understat' and (p.source_player_id=n.source_player_id or p.player_code=n.player_code)) then raise exception 'Existing identity claim; review required'; end if;
 if exists(select 1 from remediation_mappings n where (select count(*) from source_player_match_stats s where s.source='understat' and s.source_player_id=n.source_player_id and s.player_code is null)<>n.expected_rows) then raise exception 'Staged source set changed'; end if;
end $$;
create temp table remediation_targets on commit drop as
select p.id,s.season,s.source_match_id,s.source_player_id,n.player_code,s.xg,s.xa,s.shots,s.key_passes,s.xg_chain,s.xg_buildup
from remediation_mappings n join source_player_match_stats s on s.source='understat' and s.source_player_id=n.source_player_id
join player_match_stats p on p.season=s.season and p.match_id=s.match_id and p.player_code=n.player_code
where p.advanced_source is null;
do $$ begin
 if (select count(*) from remediation_targets)<>769 or (select count(distinct id) from remediation_targets)<>769 then raise exception 'Enrichment cardinality/source precondition failed'; end if;
end $$;
insert into player_source_ids(source,source_player_id,player_code,mapping_method,verified,source_note)
select 'understat',source_player_id,player_code,mapping_method,true,source_note from remediation_mappings;
update source_player_match_stats s set player_code=n.player_code,data_quality='source_reported_verified_cross_source_identity',updated_at=now()
from remediation_mappings n where s.source='understat' and s.source_player_id=n.source_player_id and s.player_code is null;
update player_match_stats p set xg=t.xg,xa=t.xa,shots=t.shots,key_passes=t.key_passes,xg_chain=t.xg_chain,xg_buildup=t.xg_buildup,advanced_source='understat',advanced_source_match_id=t.source_match_id,advanced_source_player_id=t.source_player_id
from remediation_targets t where p.id=t.id and p.advanced_source is null;
do $$ begin
 if exists(select 1 from remediation_targets t join player_match_stats p using(id) where p.advanced_source is distinct from 'understat' or p.advanced_source_player_id is distinct from t.source_player_id or p.xg is distinct from t.xg or p.xa is distinct from t.xa or p.shots is distinct from t.shots or p.key_passes is distinct from t.key_passes or p.xg_chain is distinct from t.xg_chain or p.xg_buildup is distinct from t.xg_buildup) then raise exception 'Enrichment verification failed'; end if;
end $$;
select (select count(*) from remediation_mappings) as new_mappings,(select count(*) from remediation_targets) as enriched_rows,(select count(*) from remediation_targets where season='2026/27') as current_season_enriched;
commit;
